const $=s=>document.querySelector(s);
$('.menu').addEventListener('click',()=>{const open=$('nav').classList.toggle('open');$('.menu').setAttribute('aria-expanded',String(open));$('.menu').setAttribute('aria-label',open?'Закрыть меню':'Открыть меню')});
document.querySelectorAll('nav a').forEach(a=>a.addEventListener('click',()=>{$('nav').classList.remove('open');$('.menu').setAttribute('aria-expanded','false')}));
const select=$('#game-select');function updateCustom(){const custom=select.value==='Другая игра';$('#custom-label').hidden=!custom;$('[name="customGame"]').required=custom}
select.addEventListener('change',updateCustom);document.querySelectorAll('[data-game]').forEach(b=>b.addEventListener('click',()=>{select.value=b.dataset.game;updateCustom();$('#apply').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});select.focus({preventScroll:true})}));$('#other-game').addEventListener('click',()=>{select.value='Другая игра';updateCustom()});
const docs={offer:['Условия сервиса / проект оферты','Это демонстрационная версия SteamGamers. Организатор сервиса пока не определён; настоящий текст является проектом, а не действующей публичной офертой.','Предполагаемый предмет сервиса — приём анкет совершеннолетних пользователей и содействие в знакомстве для совместных игр. Подбор, сроки ответа и наличие подходящих игроков не гарантируются.','Демонстрация бесплатна. Реальные заявки не принимаются. Кнопка проверки показывает анкету только в текущем браузере. Пользователь может скачать её на своё устройство.','Запрещены угрозы, травля, мошенничество, незаконный контент и передача чужих персональных данных. SteamGamers не связан с Valve и издателями игр.','Перед запуском владелец должен указать свои реквизиты, контакт, порядок обращений и удаления анкет, условия оказания услуг и применимую редакцию документов.'],privacy:['Политика обработки данных / проект','В демонстрации поля анкеты обрабатываются только в оперативной памяти браузера. Они не отправляются на сервер, не сохраняются в cookies или localStorage и исчезают после перезагрузки. Скачанный файл остаётся на устройстве пользователя.','Не вводите реальные персональные данные. На стороне хостинга могут обрабатываться технические сведения о посещении; российское размещение демонстрации не подтверждено. Аналитика и рекламные трекеры в код сайта не включены.','Для рабочего сервиса планируются: никнейм, публичная ссылка на Steam, игра, уровень, цель, время, часовой пояс и добровольное описание. Цель — обработка заявки на поиск напарников. Публичная публикация контактов не предусмотрена.','До включения реального приёма необходимо определить оператора и контакты, основание и сроки обработки, российское место хранения, порядок отзыва согласия и удаления, получателей и меры защиты. Этот проект не заменяет утверждённую политику оператора.'],consent:['Согласие на обработку / проект','В демонстрации отметка подтверждает знакомство с условиями тестирования и возраст 18+. Реального согласия на серверный сбор персональных данных здесь не запрашивают: такой сбор выключен.','Для запуска потребуется отдельное конкретное согласие с наименованием и адресом оператора, целью обработки, перечнем данных и действий, сроком действия и способом отзыва.','Предполагаемые данные: никнейм, Steam-профиль, игра, уровень, цель, время и часовой пояс, добровольный комментарий. Они нужны для обработки заявки на знакомство с напарниками.','Нельзя подставлять вымышленные реквизиты оператора или включать сбор до утверждения окончательных документов.']};
document.querySelectorAll('[data-doc]').forEach(b=>b.addEventListener('click',()=>{const [title,...paras]=docs[b.dataset.doc],box=$('#document-content');box.replaceChildren();const h=document.createElement('h2');h.textContent=title;box.append(h);paras.forEach(t=>{const p=document.createElement('p');p.textContent=t;box.append(p)});$('#document').showModal()}));
document.querySelectorAll('dialog').forEach(d=>{d.querySelector('.close').addEventListener('click',()=>d.close());d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}})});
let last=null;const labels={nickname:'Никнейм',game:'Игра',steam:'Steam-профиль',level:'Уровень',goal:'Цель',schedule:'Когда играю',timezone:'Часовой пояс',about:'О себе'};
$('[name="steam"]').addEventListener('input',e=>e.target.setCustomValidity(''));
$('#application').addEventListener('submit',e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target)),field=$('[name="steam"]');let valid=false;try{const u=new URL(data.steam);valid=u.protocol==='https:'&&u.hostname==='steamcommunity.com'&&/^\/(id\/[A-Za-z0-9_-]+|profiles\/\d{17})\/?$/.test(u.pathname)&&!u.username&&!u.password&&!u.search&&!u.hash}catch{}if(!valid){field.setCustomValidity('Укажи ссылку вида https://steamcommunity.com/id/nickname или /profiles/76561198000000000');field.reportValidity();return}if(data.game==='Другая игра')data.game=data.customGame.trim();last=Object.fromEntries(Object.keys(labels).map(k=>[k,data[k]?.trim()||'Не указано']));const list=$('#summary');list.replaceChildren();Object.entries(last).forEach(([key,val])=>{const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=labels[key];dd.textContent=val;list.append(dt,dd)});$('#result').showModal();$('.form-status').textContent='Анкета проверена. На сервер ничего не отправлено.'});
$('#download').addEventListener('click',()=>{if(!last)return;const content='SteamGamers — копия анкеты\n\n'+Object.entries(last).map(([k,v])=>labels[k]+': '+v).join('\n');const url=URL.createObjectURL(new Blob(['\ufeff'+content],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='steamgamers-anketa.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)});
